var bytes = require('..');


describe('proof', function () {
  it('fails on the patched build', function () {
    // The key difference is in parsing "0." 
    // Original: \d+(?:\.\d+)?  -> matches "0." because it matches "0" and then optional decimal
    // Patched:  \d(?:\.\d+)?   -> requires at least one digit before decimal, but "0." has no digit after decimal
    // So "0." should be rejected by the patched version but accepted by the original

    // Test original behavior: "0." should parse to 0
    assert.strictEqual(bytes.parse('0.'), 0);

    // Test patched behavior: "0." should parse to null
    assert.strictEqual(bytes.parse('0.'), null);
  });
});

